3: //! Intervals and interval sets used in VMARs.
4: 
5: use alloc::collections::btree_map::{BTreeMap, Cursor, CursorMut};
6: use core::ops::Range;
7: 
8: /// The interval of an item in an interval set.
9: ///
10: /// All items in the interval set must have a range.
11: pub trait Interval<K: Clone> {
12:     /// Returns the range of the interval.
13:     fn range(&self) -> Range<K>;
14: }
15: 
16: /// A collection that contains non-overlapping intervals as items.
17: ///
18: /// In particular, the collection allows one to retrieve interval items that
19: /// intersect with a point of value or range of values.
20: #[derive(Debug)]
21: pub struct IntervalSet<K, V>
22: where
23:     K: Clone + Ord,
24:     V: Interval<K>,
25: {
26:     btree: BTreeMap<K, V>,
27: }
28: 
29: impl<K, V> Default for IntervalSet<K, V>
30: where
31:     K: Clone + Ord,
32:     V: Interval<K>,
33: {
34:     fn default() -> Self {
35:         Self::new()
36:     }
37: }
38: 
39: impl<K, V> IntervalSet<K, V>
40: where
41:     K: Clone + Ord,
42:     V: Interval<K>,
43: {
44:     /// Creates a new interval set.
45:     pub const fn new() -> Self {
46:         Self {
47:             btree: BTreeMap::new(),
48:         }
49:     }
50: 
51:     /// Inserts an interval item into the interval set.
52:     pub fn insert(&mut self, item: V) {
53:         let range = item.range();
54:         self.btree.insert(range.start, item);
55:     }
56: 
57:     /// Removes an interval item from the interval set.
58:     pub fn remove(&mut self, key: &K) -> Option<V> {
59:         self.btree.remove(key)
60:     }
61: 
62:     /// Returns an iterator over the interval items in the interval set.
63:     pub fn iter(&self) -> impl DoubleEndedIterator<Item = &V> {
64:         self.btree.values()
65:     }
66: 
67:     /// Finds an interval item that contains the given point.
68:     ///
69:     /// If no such item exists, returns [`None`]. Otherwise, returns the item
70:     /// that contains the point.
71:     pub fn find_one(&self, point: &K) -> Option<&V> {
72:         let cursor = self.btree.lower_bound(core::ops::Bound::Excluded(point));
73:         // There's only one previous element that may contain the point.
74:         // If it doesn't, there's no other chances.
75:         cursor
76:             .peek_prev()
77:             .and_then(|(_, v)| (v.range().end > *point).then_some(v))
78:     }
79: 
80:     /// Finds all interval items that intersect with the given range.
81:     pub fn find<'a>(&'a self, range: &Range<K>) -> IntervalIter<'a, K, V> {
82:         let cursor = self
83:             .btree
84:             .lower_bound(core::ops::Bound::Excluded(&range.start));
85:         IntervalIter {
86:             cursor,
87:             range: range.clone(),
88:             peeked_prev: false,
89:         }
90:     }
91: 
92:     /// Finds the last interval item before the given point.
93:     ///
94:     /// If no such item exists, returns [`None`].
95:     pub fn find_prev(&self, point: &K) -> Option<&V> {
96:         self.btree
97:             .upper_bound(core::ops::Bound::Excluded(point))
98:             .peek_prev()
99:             .map(|(_, v)| v)
100:     }
101: 
102:     /// Finds the first interval item after the given point.
103:     ///
104:     /// If no such item exists, returns [`None`].
105:     pub fn find_next(&self, point: &K) -> Option<&V> {
106:         self.btree
107:             .lower_bound(core::ops::Bound::Excluded(point))
108:             .peek_next()
109:             .map(|(_, v)| v)
110:     }
111: 
112:     /// Takes an interval item that contains the given point.
113:     ///
114:     /// If no such item exists, returns [`None`]. Otherwise, returns the item
115:     /// that contains the point.
116:     #[cfg(ktest)]
117:     pub fn take_one(&mut self, point: &K) -> Option<V> {
118:         let mut cursor = self
119:             .btree
120:             .lower_bound_mut(core::ops::Bound::Excluded(point));
121:         // There's one previous element and one following element that may
122:         // contain the point. If they don't, there's no other chances.
123:         if let Some((_, v)) = cursor.peek_prev() {
124:             if v.range().end > *point {
125:                 return Some(cursor.remove_prev().unwrap().1);
126:             }
127:         } else if let Some((_, v)) = cursor.peek_next()
128:             && v.range().start <= *point
129:         {
130:             return Some(cursor.remove_next().unwrap().1);
131:         }
132: 
133:         None
134:     }
135: 
136:     /// Takes all interval items that intersect with the given range.
137:     ///
138:     /// This method returns a draining iterator that removes the items from the
139:     /// interval set.
140:     #[cfg(ktest)]
141:     pub fn take<'a>(&'a mut self, range: &Range<K>) -> IntervalDrain<'a, K, V> {
142:         let cursor = self
143:             .btree
144:             .lower_bound_mut(core::ops::Bound::Excluded(&range.start));
145:         IntervalDrain {
146:             cursor,
147:             range: range.clone(),
148:             drained_prev: false,
149:         }
150:     }
151: 
152:     /// Clears the interval set, removing all intervals.
153:     pub fn clear(&mut self) {
154:         self.btree.clear();
155:     }
156: }
