158: /// An iterator that iterates over intervals in an interval set.
159: #[derive(Debug)]
160: pub struct IntervalIter<'a, K, V>
161: where
162:     K: Clone + Ord,
163:     V: Interval<K>,
164: {
165:     cursor: Cursor<'a, K, V>,
166:     range: Range<K>,
167:     peeked_prev: bool,
168: }
169: 
170: impl<'a, K, V> Iterator for IntervalIter<'a, K, V>
171: where
172:     K: Clone + Ord,
173:     V: Interval<K>,
174: {
175:     type Item = &'a V;
176: 
177:     fn next(&mut self) -> Option<Self::Item> {
178:         // There's one previous element that may intersect with the range.
179:         if !self.peeked_prev {
180:             self.peeked_prev = true;
181:             if let Some((_, v)) = self.cursor.peek_prev()
182:                 && v.range().end > self.range.start
183:             {
184:                 return Some(v);
185:             }
186:         }
187: 
188:         // Find all intersected elements following it.
189:         if let Some((_, v)) = self.cursor.next() {
190:             if v.range().start >= self.range.end {
191:                 return None;
192:             }
193:             return Some(v);
194:         }
195: 
196:         None
197:     }
198: }
199: 
200: /// A draining iterator that iterates over intervals in an interval set.

200: /// A draining iterator that iterates over intervals in an interval set.
201: #[derive(Debug)]
202: pub struct IntervalDrain<'a, K, V>
203: where
204:     K: Clone + Ord,
205:     V: Interval<K>,
206: {
207:     cursor: CursorMut<'a, K, V>,
208:     range: Range<K>,
209:     drained_prev: bool,
210: }
211: 
212: impl<K, V> Iterator for IntervalDrain<'_, K, V>
213: where
214:     K: Clone + Ord,
215:     V: Interval<K>,
216: {
217:     type Item = V;
218: 
219:     fn next(&mut self) -> Option<Self::Item> {
220:         // There's one previous element that may intersect with the range.
221:         if !self.drained_prev {
222:             self.drained_prev = true;
223:             if let Some((_, v)) = self.cursor.peek_prev()
224:                 && v.range().end > self.range.start
225:             {
226:                 return Some(self.cursor.remove_prev().unwrap().1);
227:             }
228:         }
229: 
230:         // Find all intersected elements following it.
231:         if let Some((_, v)) = self.cursor.peek_next() {
232:             if v.range().start >= self.range.end {
233:                 return None;
234:             }
235:             return Some(self.cursor.remove_next().unwrap().1);
236:         }
237: 
238:         None
239:     }
240: }
